import math
from solution import newton, golden_section, NumericalError

def exponential_functions():
    return math.exp, math.exp, math.exp

f, df, ddf = exponential_functions()
point = (0, 0)
try:
    n = newton(f, df, ddf, point, start=0)
    g = golden_section(f, point, a=-2, b=1)
    for answer in (n, g):
        if not answer['converged']:
            raise RuntimeError('No solution found within the calculation limits.')
        print(answer['x'], answer['y'], answer['distance'])
except (ValueError, RuntimeError) as error:
    print(f'Calculation failed: {error}')

import math
from solution import newton, golden_section, NumericalError

def logarithmic_functions():
    def positive(x):
        if x <= 0:
            raise NumericalError('The logarithm requires x > 0.')
        return x

    def f(x):
        return math.log(positive(x))

    def df(x):
        return 1 / positive(x)

    def ddf(x):
        return -1 / positive(x)**2

    return f, df, ddf

f, df, ddf = logarithmic_functions()
point = (0, 0)
try:
    n = newton(f, df, ddf, point, start=1)
    g = golden_section(f, point, a=0.1, b=2)
    for answer in (n, g):
        if not answer['converged']:
            raise RuntimeError('No solution found within the calculation limits.')
        print(answer['x'], answer['y'], answer['distance'])
except (ValueError, RuntimeError) as error:
    print(f'Calculation failed: {error}')
